package io.artio.bundles;

import io.artio.kernel.Aggregate; import java.util.*;

/** A bundle is a separate aggregate from merchandise products. */
public final class Bundle extends Aggregate<BundleId> {
    private BundleName name; private final BundleSku sku; private final BundleType type;
    private List<BundleComponent> components; private List<BundleOptionGroup> optionGroups;
    private BundlePricingRule pricingRule; private boolean active;
    private Bundle(BundleId id,BundleName name,BundleSku sku,BundleType type,List<BundleComponent> components,List<BundleOptionGroup> groups,BundlePricingRule pricingRule,boolean active){
        super(id);this.name=Objects.requireNonNull(name);this.sku=Objects.requireNonNull(sku);this.type=Objects.requireNonNull(type);this.pricingRule=Objects.requireNonNull(pricingRule);this.active=active;this.components=validComponents(type,components,groups);this.optionGroups=validGroups(type,groups);
    }
    public static Bundle fixed(BundleId id,BundleName name,BundleSku sku,List<BundleComponent> components,BundlePricingRule pricingRule){var b=new Bundle(id,name,sku,BundleType.FIXED,components,List.of(),pricingRule,true);b.recordEvent(new BundleCreated(id,BundleType.FIXED,b.sku));return b;}
    public static Bundle configurable(BundleId id,BundleName name,BundleSku sku,List<BundleOptionGroup> groups,BundlePricingRule pricingRule){var b=new Bundle(id,name,sku,BundleType.CONFIGURABLE,List.of(),groups,pricingRule,true);b.recordEvent(new BundleCreated(id,BundleType.CONFIGURABLE,b.sku));return b;}
    public static Bundle reconstitute(BundleId id,BundleName name,BundleSku sku,BundleType type,List<BundleComponent> components,List<BundleOptionGroup> groups,BundlePricingRule pricingRule,boolean active){return new Bundle(id,name,sku,type,components,groups,pricingRule,active);}
    public void rename(BundleName value){Objects.requireNonNull(value);if(!name.equals(value)){var old=name;name=value;recordEvent(new BundleRenamed(getId(),old,value));}}
    public void setActive(boolean value){if(active!=value){active=value;recordEvent(new BundleActiveChanged(getId(),value));}}
    public BundleConfiguration configure(Map<String,Set<UUID>> selectedOptions){Objects.requireNonNull(selectedOptions);if(!active)throw new IllegalStateException("Inactive bundles cannot be configured");var result=new ArrayList<>(components);var groupCodes=optionGroups.stream().map(BundleOptionGroup::code).collect(java.util.stream.Collectors.toSet());if(!groupCodes.containsAll(selectedOptions.keySet()))throw new IllegalArgumentException("Selection contains an unknown option group");for(var group:optionGroups){var selected=selectedOptions.getOrDefault(group.code(),Set.of());if(selected.size()<group.minimumSelections()||selected.size()>group.maximumSelections())throw new IllegalArgumentException("Invalid number of choices for option group: "+group.code());for(var id:selected){var choice=group.choices().stream().filter(c->c.sellableId().equals(id)).findFirst().orElseThrow(()->new IllegalArgumentException("Choice does not belong to option group: "+group.code()));result.add(new BundleComponent(choice.sellableId(),choice.quantity()));}}return new BundleConfiguration(getId(),result);}
    private static List<BundleComponent> validComponents(BundleType type,List<BundleComponent> components,List<BundleOptionGroup> groups){Objects.requireNonNull(components);components=List.copyOf(components);if(type==BundleType.FIXED){if(components.isEmpty()||!groups.isEmpty())throw new IllegalArgumentException("Fixed bundles require components and cannot have option groups");if(new HashSet<>(components.stream().map(BundleComponent::sellableId).toList()).size()!=components.size())throw new IllegalArgumentException("Fixed bundle components cannot repeat sellables");}else if(!components.isEmpty())throw new IllegalArgumentException("Configurable bundles define choices through option groups");return components;}
    private static List<BundleOptionGroup> validGroups(BundleType type,List<BundleOptionGroup> groups){Objects.requireNonNull(groups);groups=List.copyOf(groups);if(type==BundleType.CONFIGURABLE){if(groups.isEmpty())throw new IllegalArgumentException("Configurable bundles require option groups");if(groups.stream().mapToInt(BundleOptionGroup::minimumSelections).sum()<1)throw new IllegalArgumentException("A configurable bundle must require at least one selected component");if(new HashSet<>(groups.stream().map(BundleOptionGroup::code).toList()).size()!=groups.size())throw new IllegalArgumentException("Option group codes must be unique");}else if(!groups.isEmpty())throw new IllegalArgumentException("Fixed bundles cannot have option groups");return groups;}
    public BundleName getName(){return name;}public BundleSku getSku(){return sku;}public BundleType getType(){return type;}public List<BundleComponent> getComponents(){return components;}public List<BundleOptionGroup> getOptionGroups(){return optionGroups;}public BundlePricingRule getPricingRule(){return pricingRule;}public boolean isActive(){return active;}
}
